import ballerina/io;

int v = 1;

function change() returns int {
    v = 100;
    return 9;
}

public function main() {
    map<int> m = {a: v, other: change()};
    io:println(m); // @output {"a":1,"other":9}
    v = 1;
    int[] l = [v, change()];
    io:println(l); // @output [1,9]
    v = 1;
    int s = v + change();
    io:println(s); // @output 10
}

